// CSD_RATIONALE_BEGIN
// Best result so far (attempt 43/45): 52.0% accuracy, 99%/96% syntax.
// Primary failure: 132-144 syntax_valid_wrong (mode_A: 133 short queries semantically
// wrong; mode_B: 8 runaway long queries; mode_D: 3 syntax-invalid).
//
// Root-cause diagnosis:
//   (A) Short queries close correctly but pick wrong tables/columns. Schema-token
//       boost was 6.0 — raising to 8.0 steers harder toward schema vocabulary.
//   (B) Runaway generation (example 3: 895 tokens, repeating SUM(CASE ...).
//       Previously Phase 4 got only 80 steps. Fix: reserve 100 steps for Phase 4
//       by guarding Phase 3 with `steps + 100 < maxSteps`.
//   (C) 12 syntax_invalid cases (wrong_without_constrained_activity). Phase 4
//       budget was too small when Phase 3 ran nearly to maxSteps.
//   (D) Alias usage (e.g., `t.name` vs `teacher.name`). Guidance now explicitly
//       discourages aliases and promotes table.column notation.
//
// Changes from best attempt (43):
//   1. Guidance: add "no aliases, use table.column format" explicit instructions.
//   2. Phase 3 guard: `steps + 100 < maxSteps` instead of `steps < maxSteps`
//      — guarantees 100 steps remain for Phase 4.
//   3. Phase 3 schema boost raised from 6.0 → 8.0 (stronger grounding).
//   4. Phase 4 budget raised from 80 → 100 steps.
//   5. No other structural changes — avoid regressions from attempts 42/44/45.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so the flag flips
//   true only when RenderedEndsWith fires; we set currentConstrainedOut := [] which
//   satisfies IsValidPrefix([]) by method precondition. EOS path leaves flag false
//   (vacuously true). All other branches leave inside/current unchanged.
//
// Phase 2 OpenConstrainedSpan: Only runs when !insideConstrainedOut. Helper sets
//   currentConstrainedOut := []; IsValidPrefix([]) holds by precondition. ✓
//
// Phase 3 main loop:
//   IsCompletePrefix branch: CloseConstrainedSpan sets insideConstrainedOut := false,
//   making the implication vacuously true; currentConstrainedOut := []. ✓
//   Normal-step branch: GroupBoostedConstrainedStep hard-masks to parser-valid tokens
//   plus EOS; AppendConstrainedToken extends currentConstrainedOut by one valid token,
//   preserving IsValidPrefix by the parser-extension contract. ✓
//   EOS+close path: CloseConstrainedSpan sets insideConstrainedOut := false. ✓
//   EOS no-close path: break without state mutation, invariant unchanged. ✓
//
// Phase 4: CloseSpanWithinBudget postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1 token
//   (0 on EOS, 1 on non-EOS). Invariant preserved per iteration.
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<"
//   token. Net 1 token per 1 step; invariant preserved.
// Phase 3: Normal branch: steps += 1 (GroupBoostedConstrainedStep), AppendConstrainedToken
//   appends 1 token. Net 1:1. IsCompletePrefix branch: steps += 1 (CloseConstrainedSpan)
//   appends at most 1 ">>" token. Net ≤ 1:1. EOS+close: steps += 2, generated grows
//   by at most 1 (the close delimiter). Each iteration steps grows by ≥ 1, so
//   `maxSteps - steps` strictly decreases; the decreases clause is valid.
// Phase 4: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated| + budget.
//   steps increases by closeBudget = min(100, maxSteps - steps). So
//   steps_after = steps_before + closeBudget <= maxSteps. |generated| <= |generatedPrefix|
//   + steps_after follows from the above and the pre-Phase-4 invariant. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a SQL SELECT statement using ONLY the exact table and column names from the schema. Do NOT use table aliases or AS. Use full table_name.column_name notation in SELECT. Put exact table names in FROM and JOIN clauses without abbreviations. Include WHERE for filtering, GROUP BY for grouping, ORDER BY for sorting. Keep query as simple as possible.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) – let model emit "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" open if model did not emit it naturally
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard parser control + schema-token boosting.
// Guard `steps + 100 < maxSteps` reserves 100 steps for Phase 4 close,
// preventing both runaway generation and Phase-4 budget exhaustion.
while steps + 100 < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 8.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: Close the span if still open – up to 100 reserved steps
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 100 {
    closeBudget := remaining;
  } else {
    closeBudget := 100;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

